{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, count(*) AS n, avg(value) AS avg_value FROM abnormal_metrics WHERE service_name = 'search' AND metric = 'k8s.deployment.available' GROUP BY ALL", "claim": "Search deployment reports available=0 across the abnormal window, versus available=1 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) AS spans FROM abnormal_traces WHERE service_name IN ('search','geo','rate') GROUP BY ALL", "claim": "Search emits no spans in the abnormal window; geo and rate, which only search calls, emit none either."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS c FROM abnormal_logs WHERE level = 'ERROR' GROUP BY ALL ORDER BY c DESC", "claim": "Frontend logs 513 'Search service failed' errors in the abnormal window, and no other service logs errors."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code AS code, count(*) AS n, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE 'HTTP%' GROUP BY ALL ORDER BY n DESC", "claim": "Frontend HTTP /hotels returns 500 about 1004 times in abnormal, failing in about 0.1 ms, while other frontend paths stay 200."}
    ]}
  ]
}
